import json, re, os
_MAP = json.load(open(os.path.join(os.path.dirname(__file__), 'refmap_base.json')))
_INV = {v: int(k) for k, v in _MAP.items()}


def C(s):
    def f(m):
        nums = [_INV[int(x)] for x in m.group(1).split(',')]
        return '[' + '，'.join(str(n) for n in nums) + ']'
    return re.sub(r'\{c:([\d,]+)\}', f, s)


